SET NAMES utf8mb4;

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Первый стоматологический осмотр и комплексное планирование лечения',
'<p>Комплексный первый осмотр — это выслушивание жалобы, сбор медицинского и стоматологического анамнеза, клиническая оценка полости рта и окружающих тканей и совместное истолкование только тех записей, которые сочтены необходимыми. План лечения формируется поэтапно на основе этих данных, приоритетов пациента и подходящих вариантов.</p>
<p><img src="/assets/uploads/images/ts18-ilk-dis-muayenesi-gorusme.webp" alt="Выслушивание причины обращения и ожиданий пациента на первом осмотре" loading="lazy"  /></p>
<h2>Причина обращения и ожидания</h2>
<p>Боль, эстетические ожидания, затруднение при жевании, отсутствующие зубы, имеющиеся реставрации и приоритеты фиксируются со слов самого пациента. Первая цель — не выбрать процедуру, а понять потребности и критерии, по которым принимается решение.</p>
<h2>Медицинский и стоматологический анамнез</h2>
<p>Выясняются системные заболевания, аллергии, возможная беременность, перенесённые операции и лечение, принимаемые препараты и прошлый стоматологический опыт. При необходимости запрашивается мнение лечащего врача пациента; пациент не отменяет препараты по собственному решению. О планировании лечения при беременности см. страницу <a href="/ru/hamilelikte-dis-tedavisi/">Лечение зубов при беременности</a>.</p>
<h2>Осмотр вне полости рта и мягких тканей</h2>
<p>Систематически оцениваются симметрия лица, движения челюсти, лимфатические узлы и другие необходимые внеротовые признаки, а также мягкие ткани — губы, щёки, язык, нёбо и дно полости рта. При выявлении подозрительного признака планируются дальнейшая оценка и необходимые исследования.</p>
<h2>Зубы и имеющиеся реставрации</h2>
<p>По клиническим данным оцениваются подозрение на <a href="/ru/dis-curugu-kompozit-dolgu/">кариес</a>, сколы и стираемость, изменения цвета, чувствительность, подвижность зубов, состояние пломб, коронок и мостов, а также участки отсутствующих зубов. При необходимости добавляются тесты витальности и другие вспомогательные исследования.</p>
<p><img src="/assets/uploads/images/ts18-kapsamli-agiz-dis-muayenesi.webp" alt="Систематический осмотр зубов, дёсен и тканей полости рта" loading="lazy"  /></p>
<h2>Оценка дёсен и пародонта</h2>
<p>Оцениваются налёт и зубной камень, кровоточивость, рецессия десны, глубина карманов, опорные ткани и показатели риска. Состояние дёсен может изменить очерёдность лечения перед имплантологическими, ортопедическими или эстетическими вмешательствами.</p>
<h2>Как данные осмотра используются вместе?</h2>
<table>
<thead><tr><th>Запись</th><th>Что она даёт</th><th>Принцип использования</th></tr></thead>
<tbody>
<tr><td>Клинический осмотр</td><td>Данные о зубах, дёснах, мягких тканях, височно-нижнечелюстном суставе и смыкании</td><td>Базовая оценка, объём которой у каждого пациента определяется потребностью</td></tr>
<tr><td>Рентгенологическая запись</td><td>Оценка недоступных глазу корней, кости и контактных поверхностей</td><td>Только тот снимок, который необходим по анамнезу, прежним записям и клиническим данным</td></tr>
<tr><td>Фотографии / цифровое сканирование</td><td>Запись, помогающая задокументировать исходное состояние, зубной ряд и смыкание</td><td>В зависимости от вида лечения и задач планирования; сама по себе не является окончательным диагнозом</td></tr>
</tbody>
</table>
<p><strong>Важно:</strong> панорамный снимок, компьютерная томография, фотографии или цифровое сканирование не являются автоматическим пакетом для каждого пациента. Оцениваются давность и диагностическая достаточность прежних записей; новая запись делается только при клинической необходимости.</p>
<p><img src="/assets/uploads/images/ts18-klinik-radyografik-dijital-degerlendirme.webp" alt="Совместная оценка клинических, рентгенологических и цифровых данных" loading="lazy"  /></p>
<h2>Смыкание, сустав и функция</h2>
<p>Оцениваются контакты зубов, характер жевания, открывание рта, жалобы со стороны сустава и мышц, привычка сжимать зубы и скрежетать ими, а также признаки стираемости. Любой звук или участок стираемости сам по себе не означает заболевания или необходимости каппы.</p>
<h2>Выбор метода визуализации</h2>
<p>Прикусный, периапикальный, панорамный снимок или трёхмерная визуализация выбираются по данным осмотра и планируемому вмешательству. Подход с назначением томографии каждому пациенту не применяется; ожидаемый диагностический вклад оценивается вместе с лучевой нагрузкой.</p>
<h2>Роль цифровых записей</h2>
<p>Записи, полученные внутриротовым сканером, стандартные фотографии и цифровые модели помогают задокументировать исходное состояние, смыкание и реставрационный план. Результат работы программы не заменяет врачебный осмотр и клиническую проверку.</p>
<h2>Диагноз и оценка риска</h2>
<p>Вместе рассматриваются кариес, заболевания дёсен, проблемы пульпы и тканей у верхушки корня, риск перелома, гигиена, курение, питание и привычки ухода. По данным, которые не удаётся уточнить, может планироваться наблюдение или дополнительное исследование.</p>
<h2>Поэтапный план лечения</h2>
<ol>
<li>Контроль острой боли и инфекции</li>
<li>Остановка заболевания и базовое здоровье дёсен</li>
<li>Окончательные реставрационные, хирургические или ортопедические этапы</li>
<li>Уход и индивидуально определённый интервал контрольных осмотров</li>
</ol>
<p>Клиническая ситуация может изменить эту очерёдность. О том, какие разделы содержит план и как он обновляется, см. страницу <a href="/ru/tedavi-plani-ve-surec/">План лечения и его ход</a>.</p>
<p><img src="/assets/uploads/images/ts18-asamali-tedavi-plani-ve-bilgilendirme.webp" alt="Разъяснение пациенту поэтапного плана лечения" loading="lazy"  /></p>
<h2>Варианты и ход процесса</h2>
<p>Понятным языком обсуждаются цель каждого применимого варианта, его существенные преимущества и риски, альтернативы, возможные последствия отказа от лечения, а также предполагаемые сроки и объём. План может обновляться с учётом новых клинических данных или реакции на заживление. Информированное согласие — не просто подпись, а процесс понятного информирования и возможности задавать вопросы.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Проводится ли лечение сразу на первом осмотре?</strong><br>Не всегда. Приоритет — оценка и безопасное планирование. Острая боль или подходящее несложное вмешательство могут быть выполнены в тот же день, если позволяет время и получено согласие. Комплексное лечение чаще всего начинается после планирования.</p>
<p><strong>Всем ли пациентам назначают панорамный снимок?</strong><br>Нет. Вид и время визуализации определяются по анамнезу, клиническому осмотру, прежним снимкам и планируемому вмешательству. Если имеющихся записей достаточно, лишнее повторение не проводится.</p>
<p><strong>Как определяется очерёдность в плане лечения?</strong><br>Сначала идут неотложные состояния и контроль инфекции; после завершения базовых этапов, таких как лечение дёсен и кариеса, планируются окончательные реставрации, имплантация и протезирование или эстетические вмешательства.</p>
<p><strong>Могу ли я принести имеющиеся записи для второго мнения?</strong><br>Да. Рентгеновские снимки, заключения, сведения об имплантах и записи о прежнем лечении могут помочь в оценке. Однако если их давность или качество изображения недостаточны, может потребоваться дополнительная запись.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт первый осмотр рассматривается как комплексный процесс планирования, в котором вместе оцениваются жалоба, медицинский анамнез, здоровье зубов и дёсен, смыкание и только необходимые клинические и цифровые записи.</p>
<p><a href="/ru/acil-dis-agrisinda-ilk-24-saat/">Острая зубная боль</a> &middot; <a href="/ru/tedavi-plani-ve-surec/">План лечения и его ход</a> &middot; <a href="/ru/dental-implant-tedavisi/">Дентальная имплантация</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Узнайте о медицинском анамнезе, оценке дёсен и смыкания, необходимых рентгеновских снимках, цифровых записях и поэтапном плане лечения при первом стоматологическом осмотре.',
'Первый стоматологический осмотр и план лечения | MSc. Dt. Mehmet Taş',
'RU' FROM pages WHERE link = 'ilk-dis-muayenesi-tedavi-planlamasi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'План лечения и прозрачность процесса: что определяет его объём?',
'<p>В стоматологическом лечении неопределённость чаще всего вызывает больше тревоги, чем само лечение. Когда после осмотра в письменном виде сообщается, какие вмешательства будут выполнены, за сколько этапов они завершатся и в какой очерёдности, пациент принимает решение, располагая информацией. Эта страница рассказывает, как устроен процесс, ещё до обращения в клинику.</p>
<p><img src="/assets/uploads/images/ts90-01-tedavi-plani-gorusmesi.webp" alt="Обсуждение плана лечения врачом с пациентом" loading="lazy"  /></p>
<h2>Что содержит план лечения?</h2>
<table>
<thead><tr><th>Раздел</th><th>Пояснение</th></tr></thead>
<tbody>
<tr><td>Клинические данные</td><td>Состояние, выявленное по итогам осмотра и необходимой визуализации.</td></tr>
<tr><td>Предлагаемые вмешательства</td><td>Понятное изложение того, какое вмешательство предлагается для какого зуба.</td></tr>
<tr><td>Альтернативы</td><td>Другие подходы, которые можно рассмотреть при той же проблеме, и различия между ними.</td></tr>
<tr><td>Этапы и очерёдность</td><td>Какое вмешательство следует выполнить раньше и почему.</td></tr>
<tr><td>Предполагаемый ход</td><td>Примерное число приёмов и ожидаемые периоды ожидания для заживления.</td></tr>
<tr><td>Что будет, если не лечить?</td><td>Возможное развитие событий при откладывании лечения.</td></tr>
<tr><td>Потребность в уходе</td><td>Ожидания по контрольным осмотрам и ежедневному уходу после лечения.</td></tr>
</tbody>
</table>
<p>При комплексных планах эти сведения, помимо устного разъяснения, передаются и в письменном виде; у пациента есть время подумать и задать вопросы.</p>
<h2>Что определяет объём плана?</h2>
<p>У двух людей с одной и той же жалобой план лечения может быть разным. Основные факторы, определяющие объём:</p>
<ul>
<li>Характер проблемы, её распространённость и то, насколько она продвинулась</li>
<li>Сохранившиеся здоровые ткани зуба и состояние опоры дёсен и кости</li>
<li>Характер смыкания, привычка сжимать зубы и скрежетать ими</li>
<li>Общее состояние здоровья, принимаемые препараты, курение</li>
<li>Привычки гигиены полости рта и возможность приходить на контрольные осмотры</li>
<li>Выбранный метод, используемый материал и лабораторный этап</li>
<li>Необходимость подготовительных вмешательств (лечение дёсен, увеличение объёма кости, ортодонтическая подготовка и т. п.)</li>
</ul>
<p>Без осмотра план составить нельзя. Точные сведения о лечении и его объёме, данные по телефону, в переписке или по фотографии, не являются достоверными. Предварительная беседа даёт лишь общее представление; план формируется после клинического осмотра и необходимой визуализации.</p>
<p><img src="/assets/uploads/images/ts90-03-muayene-ve-degerlendirme.webp" alt="Совместное проведение осмотра и рентгенологической оценки" loading="lazy"  /></p>
<h2>Поэтапное планирование и порядок приоритетов</h2>
<p>При комплексном лечении не всё делается одновременно. В общем виде соблюдается такая очерёдность:</p>
<table>
<thead><tr><th>Этап</th><th>Содержание</th></tr></thead>
<tbody>
<tr><td>1 — Неотложный</td><td>Состояния, не терпящие отлагательства: боль, инфекция, отёк и травма.</td></tr>
<tr><td>2 — Остановка заболевания</td><td><a href="/ru/dis-curugu-kompozit-dolgu/">Лечение кариеса</a>, лечение дёсен, упорядочение гигиены полости рта.</td></tr>
<tr><td>3 — Восстановление</td><td>Пломбы, коронки, <a href="/ru/kanal-tedavisi/">лечение корневых каналов</a>, <a href="/ru/dental-implant-tedavisi/">восполнение отсутствующих зубов</a>.</td></tr>
<tr><td>4 — Эстетика</td><td>Необязательные эстетические вмешательства; после устранения проблем со здоровьем.</td></tr>
<tr><td>5 — Профилактика и наблюдение</td><td>Регулярные осмотры, профессиональная чистка, при необходимости ночная каппа.</td></tr>
</tbody>
</table>
<p>Такая очерёдность нужна, чтобы основание, на котором строится работа, было прочным. Долгосрочный результат эстетической реставрации, выполненной при продолжающемся воспалении дёсен, может пострадать.</p>
<p><img src="/assets/uploads/images/ts90-02-asamali-planlama.webp" alt="Схема, показывающая разделение плана лечения на этапы" loading="lazy"  /></p>
<h2>Может ли план измениться?</h2>
<p>Да. В стоматологии часть данных становится видна только во время вмешательства: например, глубина кариеса окончательно выясняется при его удалении, и может обнаружиться необходимость лечения корневых каналов. В таких случаях, прежде чем продолжить, пациенту сообщают об этом и получают его согласие. Обновление плана не означает, что первоначальная оценка была ошибочной.</p>
<h2>Социальное страхование (SGK) и стоматологическое лечение</h2>
<p>Права на стоматологическое лечение в рамках Учреждения социального обеспечения (SGK) различаются в зависимости от типа учреждения, в которое вы обратились. Услуги в области здоровья полости рта и зубов предоставляются в государственных медицинских учреждениях и в учреждениях, имеющих договор с SGK, в объёме, определённом законодательством.</p>
<p><strong>У нашей клиники нет договора с Учреждением социального обеспечения.</strong> Эти сведения приведены здесь прямо, поскольку их следует знать до записи на приём. При изменении законодательства или статуса договора этот раздел будет обновлён.</p>
<h2>Вопросы, которые вы можете задать врачу</h2>
<ul>
<li>Какие вмешательства предлагаются в моём случае и почему?</li>
<li>Каковы альтернативы этому лечению? В чём между ними разница?</li>
<li>Что нужно сделать сейчас, а что может подождать?</li>
<li>Сколько приёмов предполагается? Какой перерыв будет между приёмами?</li>
<li>Что нормально чувствовать после вмешательства и в каком случае мне следует вам позвонить?</li>
<li>Что будет, если я не стану проходить это лечение?</li>
<li>Какой уход и режим контрольных осмотров потребуются потом?</li>
<li>Могу ли я получить сведения об используемом материале?</li>
<li>Как меня проинформируют, если план изменится во время лечения?</li>
</ul>
<h2>Ваши персональные данные</h2>
<p>Сведения, полученные при осмотре, визуализации и лечении, относятся к персональным данным особой категории. О том, с какой целью эти данные обрабатываются, сколько времени хранятся и какими правами вы обладаете, рассказывается в <a href="/ru/sayfa/kvkk-aydinlatma-metni">политике обработки персональных данных</a>. Через форму записи не запрашиваются подробные сведения о здоровье или изображения; при необходимости безопасный способ передачи сообщается отдельно.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Можно ли узнать объём лечения по телефону?</strong><br>Поскольку объём лечения нельзя определить без осмотра, точные сведения по телефону не предоставляются. После осмотра индивидуальный план передаётся вам в письменном виде.</p>
<p><strong>Могу ли я взять время на обдумывание плана лечения?</strong><br>Да. Если нет неотложного состояния, естественно, что вы возьмёте время на оценку плана. Вопросы вы можете задать и позже.</p>
<p><strong>Могу ли я захотеть услышать мнение другого врача?</strong><br>Да. Получить второе мнение — право пациента. По вашему запросу имеющиеся записи могут быть предоставлены.</p>
<p><strong>Что происходит, если план меняется во время лечения?</strong><br>Прежде чем продолжить, ситуацию разъясняют, сообщают варианты и получают ваше согласие.</p>
<p><strong>Что взять с собой на приём?</strong><br>Документ, удостоверяющий личность, имеющиеся прежние снимки и записи о лечении, список принимаемых препаратов и сведения об известных заболеваниях или аллергиях. Если есть заключение от другого врача, возьмите его с собой.</p>
<p><strong>Могу ли я получить счёт и документы?</strong><br>По выполненным вмешательствам оформляются документы в соответствии с законодательством. По вашему запросу выдаётся копия ваших лечебных записей.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт план лечения формируется на основе совместной оценки клинического осмотра, необходимой визуализации и ожиданий пациента и передаётся пациенту.</p>
<p><a href="/ru/dental-implant-tedavisi/">Дентальная имплантация</a> &middot; <a href="/ru/kanal-tedavisi/">Лечение корневых каналов</a> &middot; <a href="/ru/sayfa/kvkk-aydinlatma-metni">Политика обработки персональных данных</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Что включает план лечения и что определяет его объём? Что нужно знать до приёма и какие вопросы задать.',
'План лечения и прозрачность процесса | MSc. Dt. Mehmet Taş',
'RU' FROM pages WHERE link = 'tedavi-plani-ve-surec';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Что делать в первые 24 часа при острой зубной боли?',
'<p><strong>У вас болит зуб прямо сейчас?</strong> <a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> &middot; <a href="https://www.google.com/maps/dir/?api=1&amp;destination=41.0173894%2C28.6465901" target="_blank" rel="noopener">Как доехать</a></p>
<p>Сильная зубная боль чаще всего не проходит сама; уменьшение боли не означает, что проблема исчезла. Цель первых 24 часов — безопасно справиться с болью и как можно скорее записаться на осмотр. Приведённые ниже рекомендации носят информационный характер и не заменяют осмотр.</p>
<h2>Что можно сделать сразу</h2>
<ul>
<li>Рот можно бережно прополоскать тёплой водой.</li>
<li>Если в болезненной области застряла пища, можно осторожно попробовать удалить её зубной нитью.</li>
<li>Холод снаружи на щёку (лёд, завёрнутый в ткань, с перерывами по 10–15 минут) может помочь уменьшить отёк и боль.</li>
<li>Если во время сна держать голову немного выше туловища, это может принести облегчение, особенно при усиливающейся ночью пульсирующей боли.</li>
<li>Если речь идёт о приёме обезболивающего, следует выбрать препарат, который ранее рекомендовал врач или фармацевт и который вам не противопоказан, не превышая дозу, указанную на упаковке.</li>
</ul>
<p><img src="/assets/uploads/images/ts83-05-soguk-uygulama.webp" alt="Прикладывание холодного компресса в ткани снаружи на щёку при зубной боли" loading="lazy"  /></p>
<h2>Чего следует избегать</h2>
<ul>
<li><strong>Не принимайте антибиотики без назначения.</strong> Антибиотик не устраняет источник боли; он временно маскирует картину, затрудняет постановку диагноза, а его излишнее применение способствует развитию устойчивости.</li>
<li>Не кладите на больной зуб или десну аспирин, таблетки обезболивающего, одеколон, спирт или уксус; они могут вызвать химический ожог десны.</li>
<li>При отёке не прикладывайте тепло; тёплый компресс может способствовать распространению воспаления.</li>
<li>Не пытайтесь самостоятельно вскрыть или выдавить абсцесс.</li>
<li>Не жуйте твёрдую пищу на болезненной стороне.</li>
</ul>
<p><img src="/assets/uploads/images/ts83-06-kacinilmasi-gerekenler.webp" alt="Безрецептурные препараты и тёплый компресс, которых следует избегать при зубной боли" loading="lazy"  /></p>
<h2>Признаки, требующие безотлагательного обращения</h2>
<p>Если есть хотя бы один из перечисленных ниже признаков, речь идёт не только о проблеме с зубом; следует без промедления обратиться в <strong>ближайшее отделение неотложной помощи</strong>. Ждать приёма в стоматологической клинике не нужно.</p>
<table>
<thead><tr><th>Признак</th><th>Почему это неотложно?</th></tr></thead>
<tbody>
<tr><td>Затруднение дыхания или глотания</td><td>Отёк может сужать дыхательные пути. Это угрожает жизни, следует сразу звонить в службу экстренной помощи.</td></tr>
<tr><td>Отёк, распространяющийся по дну полости рта или на шею</td><td>Может указывать на продвижение инфекции в глубокие клетчаточные пространства шеи.</td></tr>
<tr><td>Отёк, распространяющийся вокруг глаза, закрывающийся глаз</td><td>Может указывать на продвижение вверх инфекции, исходящей из верхней челюсти.</td></tr>
<tr><td>Высокая температура, озноб, слабость</td><td>Может указывать на то, что инфекция вышла за местные границы.</td></tr>
<tr><td>Невозможность открыть рот (тризм)</td><td>Может указывать на вовлечение жевательных мышц и распространение инфекции.</td></tr>
<tr><td>Не останавливающееся кровотечение</td><td>Особенно у принимающих препараты, разжижающие кровь, требуется неотложная оценка.</td></tr>
</tbody>
</table>
<p><strong>При переломе зуба или его выбивании в результате удара:</strong> держите зуб за коронковую часть, не трите корень; храните его в молоке, физиологическом растворе или слюне и обратитесь как можно скорее. Время здесь имеет решающее значение. Подробные указания для детей см. на странице <a href="/ru/cocuklarda-dis-travmasi/">Травмы зубов у детей</a>.</p>
<h2>Что делают в клинике?</h2>
<p><img src="/assets/uploads/images/ts83-01-acil-degerlendirme-gorusmesi.webp" alt="Осмотр пациента врачом при обращении с острой зубной болью" loading="lazy"  /></p>
<table>
<thead><tr><th>Шаг</th><th>Что делается</th><th>Чего ожидать</th></tr></thead>
<tbody>
<tr><td>Быстрая оценка</td><td>Выясняются локализация, длительность, характер боли и провоцирующие факторы</td><td>Определение того, требуется ли неотложное вмешательство</td></tr>
<tr><td>Клинический осмотр</td><td>Исследуются зуб, десна и окружающие ткани; может быть проведён тест витальности</td><td>Определение источника боли</td></tr>
<tr><td>Рентгенологическое исследование</td><td>При необходимости выполняется периапикальный или панорамный снимок</td><td>Визуализация состояния корня и кости</td></tr>
<tr><td>Устранение боли</td><td>В зависимости от ситуации проводятся дренирование, <a href="/ru/kanal-tedavisi/">раскрытие канала</a> или временная реставрация</td><td>Взятие боли под контроль</td></tr>
<tr><td>Представление плана</td><td>Разъясняются варианты окончательного лечения и их сроки</td><td>Письменная информация о дальнейших шагах</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts83-02-panoramik-rontgen-incelemesi.webp" alt="Исследование панорамного снимка для определения источника зубной боли" loading="lazy"  /></p>
<p>При неотложных обращениях приоритетом являются устранение боли и взятие инфекции под контроль. Окончательное лечение обычно планируется на последующих приёмах, после стихания острых явлений; подробнее см. страницу <a href="/ru/tedavi-plani-ve-surec/">План лечения и его ход</a>.</p>
<p><img src="/assets/uploads/images/ts83-03-brosurle-bilgilendirme.webp" alt="Разъяснение пациенту вариантов лечения по брошюре" loading="lazy"  /></p>
<p><img src="/assets/uploads/images/ts83-04-takip-ve-kontrol-plani.webp" alt="Обсуждение с пациентом плана контрольных осмотров и наблюдения после лечения" loading="lazy"  /></p>
<h2>Как добраться и записаться</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт рассматриваются неотложные обращения; это относится и к пациентам, приезжающим из Бююкчекмедже и соседних районов. Перед приездом важно связаться с нами по телефону или в WhatsApp — так мы подготовим очередь и расскажем, что делать по дороге.</p>
<p><strong>Вне рабочего времени:</strong> наш дежурный врач проводит первичную оценку при обращениях вне рабочего времени и в неотложных случаях и начинает лечение. При наличии перечисленных выше неотложных признаков ждать не следует — нужно обратиться в ближайшее отделение неотложной помощи.</p>
<p><a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> &middot; <a href="https://www.google.com/maps/dir/?api=1&amp;destination=41.0173894%2C28.6465901" target="_blank" rel="noopener">Как доехать</a></p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Я выпил(а) обезболивающее, и боль прошла — нужно ли всё равно идти к врачу?</strong><br>Да. Обезболивающее лишь подавляет болевой сигнал, но не устраняет состояние, которое к нему привело. Особенно при вовлечении зубного нерва боль может ненадолго утихнуть, а затем вернуться сильнее. Рекомендуется записаться на осмотр.</p>
<p><strong>Если начать принимать антибиотик, боль пройдёт?</strong><br>При некоторых инфекциях антибиотик может быть назначен врачом в дополнение к лечению, но сам по себе он не является решением, и начинать его приём самостоятельно нельзя. Источник боли чаще всего устраняется механическим вмешательством (раскрытие канала, дренирование). Излишнее применение антибиотиков и затрудняет диагностику, и способствует устойчивости к ним.</p>
<p><strong>Если зубная боль началась ночью, стоит ли ждать утра?</strong><br>Если боль удаётся контролировать лекарством и нет перечисленных выше неотложных признаков, можно записаться на приём утром. Однако при отёке, температуре, затруднении глотания или дыхания ждать утра нельзя — следует обратиться в ближайшее отделение неотложной помощи.</p>
<p><strong>Боль прошла, но на десне появился небольшой пузырёк — это важно?</strong><br>Такой пузырёк может указывать на то, что воспаление нашло себе выход. Уменьшение боли не означает выздоровления; процесс может тихо продолжаться. Рекомендуется записаться на осмотр.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт приоритетом при неотложных обращениях являются безопасное устранение боли и взятие инфекции под контроль. Окончательный план лечения составляется вместе с пациентом после стихания острых явлений.</p>
<p><a href="/ru/agiz-dis-sagligi/">Здоровье полости рта и зубов</a> &middot; <a href="/ru/kanal-tedavisi/">Лечение корневых каналов</a> &middot; <a href="/ru/dis-curugu-kompozit-dolgu/">Кариес и композитные пломбы</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Что делать в первые 24 часа при сильной зубной боли, чего избегать и при каких признаках обращаться безотлагательно? Пошаговое руководство.',
'Острая зубная боль: первые 24 часа | MSc. Dt. Mehmet Taş',
'RU' FROM pages WHERE link = 'acil-dis-agrisinda-ilk-24-saat';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Лечение зубов при беременности: безопасно ли и когда его проводить?',
'<p>Во время беременности осмотр, удаление зубных отложений, пломбирование, лечение корневых каналов и необходимое удаление зуба могут выполняться при соблюдении надлежащих мер предосторожности. Такие состояния, как боль, отёк или инфекция, откладывать нельзя; оставленная без лечения инфекция может создать больший риск и для матери, и для ребёнка. Необязательные эстетические вмешательства, как правило, переносятся на период после родов. Важно сообщать врачу о беременности и её сроке на каждом приёме.</p>
<h2>Что меняется в полости рта при беременности?</h2>
<table>
<thead><tr><th>Изменение</th><th>Пояснение</th></tr></thead>
<tbody>
<tr><td>Гингивит беременных</td><td>Гормональные изменения делают десну более чувствительной к налёту; часто наблюдаются покраснение, отёчность и кровоточивость при чистке.</td></tr>
<tr><td>Разрастание на десне</td><td>У части женщин на десне может появиться легко кровоточащее доброкачественное красное образование. Чаще всего после родов оно уменьшается; тем не менее его должен осмотреть врач.</td></tr>
<tr><td>Повышение риска кариеса</td><td>Частые перекусы, тошнота и рвота приводят к контакту с кислотой и нарушению гигиены, что может повышать риск кариеса.</td></tr>
<tr><td>Эрозия эмали</td><td>Повторяющаяся рвота может приводить к кислотному разрушению поверхности зубов.</td></tr>
</tbody>
</table>
<p>Есть исследования, сообщающие о связи между заболеваниями дёсен у будущих матерей и преждевременными родами; однако не доказано с достоверностью, что лечение дёсен во время беременности предотвращает преждевременные роды. Лечение дёсен важно для здоровья полости рта матери и должно проводиться именно с этой целью.</p>
<h2>Планирование по триместрам</h2>
<table>
<thead><tr><th>Период</th><th>Общий подход</th></tr></thead>
<tbody>
<tr><td>1-й триместр (1–13-я недели)</td><td>Осмотр и чистка могут проводиться. Поскольку тошнота может быть выраженной, длительные вмешательства, если они не срочные, могут быть перенесены на следующий период. Неотложные состояния не откладываются.</td></tr>
<tr><td>2-й триместр (14–27-я недели)</td><td>Для многих будущих матерей это наиболее комфортный период. Необходимые пломбы, <a href="/ru/kanal-tedavisi/">лечение корневых каналов</a> и лечение дёсен чаще всего планируются именно на это время.</td></tr>
<tr><td>3-й триместр (после 28-й недели)</td><td>Необходимое лечение возможно; однако долгое положение лёжа на спине может вызывать дискомфорт и падение давления, поэтому приёмы делают короткими и следят за положением тела.</td></tr>
</tbody>
</table>
<p>Это общая схема; план определяется индивидуально с учётом течения беременности и рекомендаций вашего акушера-гинеколога.</p>
<h2>На что обращают внимание в клинике?</h2>
<p><img src="/assets/uploads/images/ts79-01-unit-pozisyonu.webp" alt="Беременная пациентка в стоматологическом кресле с опорой, слегка повёрнутая на левый бок" loading="lazy" /></p>
<table>
<thead><tr><th>Тема</th><th>Пояснение</th></tr></thead>
<tbody>
<tr><td>Информирование</td><td>Следует сообщить срок беременности, принимаемые витамины и препараты, наличие осложнённой беременности и рекомендации вашего акушера-гинеколога.</td></tr>
<tr><td>Местная анестезия</td><td>Местные анестетики, применяемые в стоматологии, могут использоваться при беременности в дозах, которые врач сочтёт подходящими. Лечиться с болью может быть более стрессовым, чем применение анестезии.</td></tr>
<tr><td>Рентген</td><td>Выполняется, только если он действительно необходим для диагностики. Лучевая нагрузка при стоматологических снимках очень низкая, и снимки делают с применением защитных мер.</td></tr>
<tr><td>Препараты</td><td>Если требуется обезболивающее или антибиотик, выбираются варианты, считающиеся безопасными при беременности, при необходимости с учётом мнения вашего акушера-гинеколога. Не принимайте лекарства самостоятельно.</td></tr>
<tr><td>Положение тела</td><td>На поздних сроках вместо положения полностью на спине комфортнее сидеть полувертикально с поворотом влево. При головокружении, тошноте или одышке сразу скажите об этом врачу.</td></tr>
<tr><td>Длительность приёма</td><td>Предпочтительны короткие приёмы с частыми перерывами.</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts79-02-gebelik-bilgisi-paylasimi.webp" alt="Беременная пациентка сообщает стоматологу сведения о беременности и здоровье" loading="lazy" /></p>
<h2>Уход дома и тошнота</h2>
<p><img src="/assets/uploads/images/ts79-03-bulanti-sonrasi-calkalama.webp" alt="Полоскание рта водой после приступа тошноты при беременности" loading="lazy" /></p>
<p>Рекомендуется чистить зубы дважды в день фторидной пастой и мягкой щёткой, а также ежедневно очищать межзубные промежутки. Не прекращайте чистку из-за кровоточивости дёсен; кровоточивость чаще всего является признаком скопления налёта и уменьшается при регулярной и бережной гигиене.</p>
<p>После рвоты не чистите зубы сразу — прополощите рот водой и подождите некоторое время; размягчённая кислотой поверхность эмали легче стирается щёткой. Если при чистке возникает тошнота, попробуйте щётку с маленькой головкой и пасту с менее выраженным вкусом. Если частые перекусы необходимы, вместо сладких и липких продуктов можно выбирать сыр, йогурт, овощи.</p>
<p><img src="/assets/uploads/images/ts79-04-yumusak-fircayla-fircalama.webp" alt="Бережная чистка мягкой щёткой при чувствительных дёснах во время беременности" loading="lazy" /></p>
<h2>Вмешательства, которые можно отложить</h2>
<p>Эстетические процедуры, такие как <a href="/ru/dis-beyazlatma/">отбеливание зубов</a>, виниры или коронки, необязательная <a href="/ru/dental-implant-tedavisi/">имплантологическая хирургия</a> и обширные эстетические переделки обычно планируются на период после родов. Это не означает, что такие вмешательства непременно вредны; цель — избежать лишних лекарств и длительных приёмов при несрочных процедурах.</p>
<p><strong>Что откладывать нельзя:</strong> сильная зубная боль, отёк лица, абсцесс, температура, травма и перелом. В этих случаях, независимо от срока беременности, следует обратиться без промедления.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Можно ли делать анестезию зуба во время беременности?</strong><br>Да. Местные анестетики, применяемые в стоматологии, могут использоваться при беременности в дозах, определённых врачом. Обязательно сообщите о беременности и об особенностях вашего состояния, если они есть.</p>
<p><strong>Делают ли рентген зубов при беременности?</strong><br>Если он необходим для диагностики, его можно сделать. Доза при стоматологических снимках очень низкая, и они выполняются с применением защитных мер. Снимок, в котором нет необходимости, откладывается.</p>
<p><strong>Дёсны кровоточат при чистке — это нормально?</strong><br>При беременности это встречается часто, но это не то состояние, которое следует оставлять без внимания. Продолжайте бережную и регулярную чистку и уход за межзубными промежутками и запишитесь на приём; при необходимости может быть проведено удаление зубных отложений.</p>
<p><strong>Удаляют ли зубы при беременности?</strong><br>Если это необходимо — да. Удаление зуба, вызывающего инфекцию или сильную боль, откладывать нельзя. Планирование проводится с учётом срока беременности и общего состояния здоровья.</p>
<p><strong>Могу ли я лечить зубы во время грудного вскармливания?</strong><br>Да. Местная анестезия и пломбирование не являются препятствием для грудного вскармливания. Если требуются лекарства, сообщите врачу, что вы кормите грудью.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт планирование лечения будущих матерей проводится с совместной оценкой срока беременности, данных клинического осмотра, общего состояния здоровья и рекомендаций вашего акушера-гинеколога. MSc. Dt. Mehmet Taş и его команда планируют длительность приёма и положение в кресле в соответствии со сроком вашей беременности.</p>
<p><a href="/ru/agiz-dis-sagligi/">Здоровье полости рта и зубов</a> · <a href="/ru/kanal-tedavisi/">Лечение корневых каналов</a> · <a href="/ru/iletisim">Запись и контакты</a></p>',
'Можно ли лечить зубы при беременности, какой период наиболее подходящий, почему кровоточат дёсны, безопасны ли анестезия и рентген? Руководство для будущих мам.',
'Лечение зубов при беременности | MSc. Dt. Mehmet Taş',
'RU' FROM pages WHERE link = 'hamilelikte-dis-tedavisi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Детская стоматология: первый осмотр, кариес молочных зубов и профилактика',
'<p>Первый осмотр ребёнка у стоматолога рекомендуется в течение шести месяцев после прорезывания первого молочного зуба или не позднее первого дня рождения. Цель этого визита чаще всего не лечение, а оценка риска кариеса, разъяснение семье правил ухода и питания в соответствии с возрастом и привыкание ребёнка к клинике. Если ребёнок познакомился с клиникой рано, в дальнейшем, когда понадобится лечение, процесс обычно проходит легче.</p>
<p><img src="/assets/uploads/images/ts87-01-ilk-muayene-kucuk-cocuk.webp" alt="Первый осмотр маленького ребёнка в стоматологическом кресле" loading="lazy"  /></p>
<p>В нашей клинике детей осматривает и лечит врач — детский стоматолог.</p>
<h2>Почему важны молочные зубы?</h2>
<p>Молочные зубы — не просто временный ряд; они выполняют функции жевания, участвуют в развитии речи и сохраняют место для постоянных зубов. В промежуток, оставшийся после рано утраченного молочного зуба, могут сместиться соседние зубы, и место, нужное постоянному зубу, может сузиться.</p>
<table>
<thead><tr><th>Функция</th><th>Пояснение</th></tr></thead>
<tbody>
<tr><td>Жевание и питание</td><td>Болезненный или поражённый кариесом зуб может ограничивать жевание и разнообразие питания ребёнка.</td></tr>
<tr><td>Развитие речи</td><td>Передние зубы участвуют в образовании некоторых звуков.</td></tr>
<tr><td>Сохранение места</td><td>Каждый молочный зуб удерживает место для постоянного зуба под ним. При ранней потере место может сузиться.</td></tr>
<tr><td>Развитие челюсти</td><td>Равномерное жевание поддерживает развитие челюстей и мышц.</td></tr>
</tbody>
</table>
<h2>Как начинается и как распознаётся кариес молочных зубов?</h2>
<p>Эмаль молочного зуба тоньше, чем у постоянного; поэтому <a href="/ru/dis-curugu-kompozit-dolgu/">кариес</a> у некоторых детей может развиваться быстрее. На ранней стадии боли может не быть, поэтому важно приходить на осмотры регулярно, не дожидаясь боли.</p>
<ul>
<li>Меловидные белые пятна у края десны (начальный признак)</li>
<li>Коричнево-чёрное изменение цвета, углубление на поверхности</li>
<li>Чувствительность к холодному, горячему или сладкому</li>
<li>Ребёнок избегает жевать одной стороной</li>
<li>Отёк десны, отёк лица или температура — в этом случае ждать нельзя</li>
</ul>
<p><img src="/assets/uploads/images/ts87-02-sut-disi-curuk-asamalari.webp" alt="Стадии кариеса молочного зуба от начального пятна до запущенной формы" loading="lazy"  /></p>
<p><strong>Бутылочка и ночные кормления:</strong> сладкие напитки или сок из бутылочки во время сна, а также частые ночные кормления связывают с быстро развивающимся кариесом передних зубов. Напитки, кроме воды, не следует давать перед сном и во время сна.</p>
<h2>Гигиена и фториды по возрасту</h2>
<p>Чистка начинается с момента появления первого зуба во рту. У маленьких детей зубы чистит родитель; в школьном возрасте, даже если ребёнок чистит сам, контроль и помощь родителя сохраняются.</p>
<table>
<thead><tr><th>Возраст</th><th>Подход</th></tr></thead>
<tbody>
<tr><td>Первый зуб – 3 года</td><td>Дважды в день, мягкая щётка с маленькой головкой. Фторидная паста размером с рисовое зёрнышко (тонкий мазок). Чистит родитель.</td></tr>
<tr><td>3 – 6 лет</td><td>Дважды в день, фторидная паста размером с горошину. Ребёнок чистит, родитель дочищает и контролирует. Ребёнка учат сплёвывать пасту, рот не полощут.</td></tr>
<tr><td>6 лет и старше</td><td>Чистка дважды в день, зубная нить на контактных поверхностях. Родительский контроль сохраняется, постепенно уменьшаясь.</td></tr>
<tr><td>Все возрасты</td><td>Тюбик пасты хранится в недоступном для ребёнка месте; пасту нельзя глотать.</td></tr>
</tbody>
</table>
<p>Подходящее количество пасты и потребность во фторидах определяет врач с учётом возраста ребёнка и риска кариеса.</p>
<p><img src="/assets/uploads/images/ts87-03-yasa-gore-macun-miktari.webp" alt="Количество зубной пасты по возрасту: сравнение рисового зёрнышка и горошины" loading="lazy"  /></p>
<h2>Профилактические процедуры</h2>
<table>
<thead><tr><th>Процедура</th><th>Когда она рассматривается?</th></tr></thead>
<tbody>
<tr><td>Герметизация фиссур</td><td>Когда глубокие углубления на жевательной поверхности моляров трудно очищать; выполняется после прорезывания зуба, при отсутствии кариеса.</td></tr>
<tr><td>Фторидный лак</td><td>Может наноситься в клинике с определёнными интервалами в зависимости от оценки риска кариеса. Частота не одинакова для всех детей.</td></tr>
<tr><td>Консультация по питанию</td><td>Пересматриваются частота употребления сахара, режим перекусов и выбор напитков.</td></tr>
<tr><td>Обучение чистке зубов</td><td>Техника показывается с учётом мануальных навыков и возраста ребёнка; определяется роль родителя.</td></tr>
</tbody>
</table>
<p>Герметизация фиссур, нанесение фторидов, установка сохранителя места и профилактические композитные реставрации полностью выполняются в нашей клинике.</p>
<p><img src="/assets/uploads/images/ts87-04-fissur-orturucu.webp" alt="Герметик, нанесённый на жевательную поверхность моляра" loading="lazy"  /></p>
<h2>Потеря зуба и сохранитель места</h2>
<p>Если молочный зуб утрачен раньше срока из-за кариеса или травмы, для ограничения смещения соседних зубов в промежуток может рассматриваться сохранитель места. Он нужен не при каждой ранней потере; решение принимается с учётом того, какой именно зуб утрачен, возраста ребёнка, стадии развития постоянного зуба под ним и рентгенологических данных.</p>
<h2>Как подготовить ребёнка к приёму</h2>
<ul>
<li>Вместо подробных пугающих историй перед приёмом рекомендуется спокойно представить визит, например как «поход посчитать зубки».</li>
<li>Важно не давать категоричных обещаний вроде «больно не будет» или «уколов не будет» — это помогает сохранить доверие.</li>
<li>Назначение приёма на время, когда ребёнок отдохнул, облегчает сотрудничество.</li>
<li>О прежнем негативном опыте, особых потребностях, если они есть, и принимаемых препаратах следует сообщить до приёма.</li>
</ul>
<p>У детей с выраженной тревогой применяется подход постепенного привыкания. Детям, которым трудно сотрудничать во время лечения, детям совсем раннего возраста или нуждающимся в обширном лечении проводят лечение под седацией; седация выполняется в нашей клинике. В случаях, требующих общего наркоза, лечение проводится в больницах-партнёрах в присутствии врача-анестезиолога и также нашим детским стоматологом. Применяемый метод выбирается вместе с семьёй после оценки возраста ребёнка, общего состояния здоровья и объёма лечения.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Когда впервые вести ребёнка к стоматологу?</strong><br>Рекомендуется в течение шести месяцев после прорезывания первого молочного зуба, но не позднее первого дня рождения. Даже при отсутствии жалоб этот визит нужен для оценки риска кариеса и составления плана ухода.</p>
<p><strong>Молочный зуб всё равно выпадет — нужно ли лечить его кариес?</strong><br>Да. Нелеченый кариес может привести к боли, инфекции, проблемам с питанием и ранней потере зуба; ранняя потеря может повлиять на положение постоянного зуба.</p>
<p><strong>Безопасна ли фторидная паста для ребёнка?</strong><br>При использовании в подходящем по возрасту количестве и под контролем фторидная паста считается полезной для профилактики кариеса. Важно, чтобы количество соответствовало возрасту и чтобы паста не проглатывалась.</p>
<p><strong>У моего ребёнка промежутки между зубами — это проблема?</strong><br>В молочном прикусе промежутки чаще всего являются ожидаемым явлением и обеспечивают место для постоянных зубов. Тем не менее оценка проводится на осмотре.</p>
<p><strong>Портят ли зубы сосание пальца или пустышка?</strong><br>В зависимости от длительности и интенсивности это может влиять на характер смыкания. При сохраняющейся привычке рассматривается подход к отказу от неё, соответствующий возрасту.</p>
<p><strong>Детская стоматология и ортодонтия — это одно и то же?</strong><br>Нет. Детская стоматология охватывает кариес, профилактику и лечение молочных зубов; положение зубов и челюстей относится к ортодонтической оценке.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт приоритетом у детей являются знакомство в период без боли и раннее выявление риска кариеса. Потребность в лечении планируется с совместной оценкой клинического осмотра, возраста ребёнка, уровня сотрудничества и необходимых данных визуализации.</p>
<p><a href="/ru/agiz-dis-sagligi/">Здоровье полости рта и зубов</a> · <a href="/ru/dis-curugu-kompozit-dolgu/">Кариес и композитные пломбы</a> · <a href="/ru/cocuklarda-dis-travmasi/">Травмы зубов у детей</a> · <a href="/ru/kanal-tedavisi/">Лечение корневых каналов</a> · <a href="/ru/iletisim">Запись и контакты</a></p>',
'Когда проводить первый стоматологический осмотр у детей, почему важен кариес молочных зубов, в каких случаях нужны фториды и сохранитель места? Руководство для родителей.',
'Детская стоматология | MSc. Dt. Mehmet Taş',
'RU' FROM pages WHERE link = 'cocuk-dis-hekimligi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Травмы зубов у детей: первая помощь при сломанном или выбитом зубе',
'<h2>Первые 30 минут: краткая сводка</h2>
<ol>
<li>Сохраняйте спокойствие, усадите ребёнка и бережно прижмите чистую марлевую салфетку к кровоточащему участку.</li>
<li>Если зуб выбит полностью, держите его за коронковую (белую, видимую) часть. Не трите корень руками, не чистите его щёткой, не высушивайте.</li>
<li><strong>Если это постоянный зуб:</strong> при загрязнении несколько секунд бережно ополосните его молоком или физиологическим раствором; по возможности установите зуб обратно в лунку. Если установить не удаётся, храните его в молоке.</li>
<li><strong>Если это молочный зуб</strong>, не пытайтесь поставить его на место. Это может повредить постоянный зуб под ним.</li>
<li>Без промедления доберитесь до клиники. При выбитом постоянном зубе решающими являются первые 30–60 минут.</li>
</ol>
<p><strong>Позвоните, прежде чем выехать:</strong> <a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> — ваше сообщение сократит время подготовки.</p>
<p><img src="/assets/uploads/images/ts88-01-dis-nasil-tutulur.webp" alt="Выбитый зуб держат за коронковую часть, не касаясь корня" loading="lazy"  /></p>
<h2>Молочный зуб или постоянный?</h2>
<p>От этого различия полностью зависит, что нужно делать. Обычно первые постоянные резцы прорезываются в возрасте 6–8 лет; у ребёнка младше этого возраста выпавший передний зуб с большой вероятностью молочный. Если уверенности нет, зуб не следует выбрасывать — его нужно привезти в клинику в молоке.</p>
<table>
<thead><tr><th>Ситуация</th><th>Молочный зуб</th><th>Постоянный зуб</th></tr></thead>
<tbody>
<tr><td>Полностью выбит</td><td>На место не устанавливается. Зуб привозят, ребёнка осматривают.</td><td>По возможности сразу устанавливается на место; если не получается, привозят в молоке.</td></tr>
<tr><td>Сломан</td><td>Отломок привозят; оценивают острый край и вскрытие пульпы.</td><td>Отломок привозят; в некоторых случаях его можно приклеить обратно.</td></tr>
<tr><td>Смещён</td><td>Оценивают положение и соседство с постоянным зубом.</td><td>Могут потребоваться репозиция и шинирование.</td></tr>
<tr><td>Срочность</td><td>Осмотр в тот же день</td><td>Важны минуты</td></tr>
</tbody>
</table>
<p><strong>Почему молочный зуб не ставят на место?</strong> Корень молочного зуба очень близок к зачатку развивающегося под ним постоянного зуба. Попытка вернуть зуб на место может необратимо повлиять на развитие и цвет постоянного зуба.</p>
<p><img src="/assets/uploads/images/ts88-02-sut-disi-daimi-dis-farki.webp" alt="Разрез, показывающий разницу в корнях и расположении молочного и постоянного зуба" loading="lazy"  /></p>
<h2>Полностью выбитый постоянный зуб</h2>
<p>Это наиболее чувствительная ко времени форма травмы зуба. Сохранность живых клеток на поверхности корня напрямую влияет на исход; поэтому главное — не дать зубу высохнуть.</p>
<h3>Что нужно делать</h3>
<ul>
<li>Зуб держат только за коронковую часть; поверхности корня не касаются.</li>
<li>При видимом загрязнении его несколько секунд ополаскивают молоком или физиологическим раствором. Не трут, не используют мыло и дезинфицирующие средства.</li>
<li>По возможности зуб бережно и в правильном направлении устанавливают в собственную лунку; ребёнок удерживает его, прикусив чистую марлевую салфетку.</li>
<li>Если установить не удаётся, зуб перевозят в молоке. Если молока нет, используют физиологический раствор.</li>
<li>Не теряя времени, едут в клинику; заранее звонят по телефону.</li>
</ul>
<h3>Чего делать нельзя</h3>
<ul>
<li>Держать зуб за корень, чистить, скрести или вытирать корень</li>
<li>Класть зуб в сухой платок, салфетку или в карман</li>
<li>Долго держать зуб в водопроводной воде</li>
<li>Давать ребёнку держать зуб во рту, если он без сознания или у него рвота</li>
</ul>
<table>
<thead><tr><th>Среда для хранения</th><th>Пригодность</th></tr></thead>
<tbody>
<tr><td>Молоко</td><td>Наиболее доступный и подходящий вариант дома и в дороге</td></tr>
<tr><td>Физиологический раствор</td><td>Подходит; можно купить в аптеке</td></tr>
<tr><td>Собственная слюна ребёнка</td><td>Может рассматриваться временно, если других вариантов нет</td></tr>
<tr><td>Водопроводная вода</td><td>Не подходит; повреждает клетки поверхности корня</td></tr>
<tr><td>Сухая среда (платок, карман)</td><td>Не подходит</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts88-03-saklama-sivisi-sut.webp" alt="Выбитый зуб хранится в ёмкости с молоком" loading="lazy"  /></p>
<h2>Сломанный зуб</h2>
<p>Лечение определяется глубиной перелома. Небольшой скол в пределах эмали и перелом со вскрытием пульпы (зубной мякоти) — не одно и то же. Если отломок найден, его следует привезти в молоке или физиологическом растворе; в отдельных случаях отломок можно приклеить обратно.</p>
<ul>
<li>Если на поверхности скола видна розовая или красная точка, есть кровотечение: возможно, вскрыта пульпа, обратиться нужно в тот же день.</li>
<li>Если острый край режет язык или губу, его можно временно закрыть мягким воском или чистой марлевой салфеткой.</li>
<li>Даже если скол не виден, в зубе, получившем удар, может появиться изменение цвета или отсроченная боль; требуется наблюдение.</li>
</ul>
<p><img src="/assets/uploads/images/ts88-04-kirik-dis-katmanlari.webp" alt="Разрез сломанного зуба со слоями эмали, дентина и пульпы" loading="lazy"  /></p>
<h2>Смещённый или вколоченный зуб</h2>
<p>Зуб может изменить положение, не выпав полностью: сместиться вперёд или назад, казаться удлинившимся либо уйти внутрь кости. В таких случаях не следует силой возвращать зуб на место — ребёнка переводят на мягкую пищу и привозят в клинику. Оценка проводится с помощью клинического осмотра и необходимых рентгеновских снимков.</p>
<h2>Случаи, требующие немедленного обращения в больницу</h2>
<p>При перечисленных ниже признаках сначала следует обратиться в отделение неотложной помощи; оценка состояния зубов проводится после этого:</p>
<ul>
<li>Потеря сознания, сонливость, повторяющаяся рвота, головокружение</li>
<li>Неостанавливающееся кровотечение</li>
<li>Заметная деформация челюсти, невозможность открыть или закрыть рот</li>
<li>Кровотечение из носа или уха, изменение зрения</li>
<li>Обширное повреждение лица, глубокий порез</li>
<li>Известное нарушение свёртываемости крови или приём препаратов, разжижающих кровь</li>
</ul>
<p>О том, как произошла травма (падение, удар, дорожное происшествие, спорт), и о прививках от столбняка следует сообщить врачу.</p>
<h2>Наблюдение после травмы</h2>
<p>Первая помощь при травме зуба — лишь начало процесса. Изменение цвета зуба, получившего удар, пузырёк на десне, боль при накусывании или подвижность могут появиться через недели, а иногда и месяцы. Поэтому за зубами после травмы наблюдают с определёнными интервалами клинически и рентгенологически. Если не пропускать контрольные приёмы, поздно развивающуюся проблему можно выявить рано.</p>
<p>У растущих детей варианты лечения после травмы зависят от стадии развития корня; поэтому план подбирается индивидуально с учётом возраста ребёнка и рентгенологических данных. И неотложную помощь, и долгосрочное наблюдение при травмах зубов у детей в нашей клинике ведёт врач — детский стоматолог.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Могу ли я сам(а) поставить выбитый зуб на место?</strong><br>Для постоянного зуба, если ребёнок спокоен и зуб не сильно загрязнён, бережно установить его на место уместно. Молочный зуб на место не ставят. Если вы не уверены, положите зуб в молоко и без промедления приезжайте в клинику.</p>
<p><strong>Можно ли промыть зуб водой?</strong><br>Водопроводная вода не подходит. Только при видимом загрязнении ополосните его несколько секунд молоком или физиологическим раствором; корень ни в коем случае не трите.</p>
<p><strong>За какое время нужно приехать?</strong><br>При выбитом постоянном зубе решающими являются первые 30–60 минут. Даже если это время прошло, зуб следует привезти, если он хранился в подходящей среде; оценка всё равно будет проведена.</p>
<p><strong>Молочный зуб выпал, на его месте вырастет новый. Нужно ли всё равно приезжать?</strong><br>Да. Необходимо оценить, не пострадал ли постоянный зуб под ним и нет ли повреждения десны и челюсти.</p>
<p><strong>Зуб потемнел — я опоздал(а)?</strong><br>Изменение цвета после травмы может появиться через недели или месяцы. Требуется оценка; не всякое изменение цвета означает одно и то же.</p>
<p><strong>Я сохранил(а) отломок — это пригодится?</strong><br>В некоторых случаях отломок можно приклеить обратно. Привезите его в молоке или физиологическом растворе, не допуская высыхания.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт при обращении детей с травмой зуба приоритетом являются определение объёма повреждения и безотлагательное выполнение чувствительных ко времени вмешательств. Звонок перед обращением сокращает время подготовки.</p>
